import { MeshBasicNodeMaterial } from 'three/webgpu';
import { } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // Geometry for the plane (size defaults to 1x1 world units)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();

  // Mesh that will display the texture
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the texture asynchronously and apply when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Store any timelines (none in this node) for cleanup
  const timelines = [];

  // User data for event handlers and cleanup
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines that might have been added in the future
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
  };

  return root;
}
